// Re-check current state before acting: the proposal must still be in the right state and its basis must still hold.
// Plans: approve books now, or sends the buyer an offer first (needs_buyer, or the employee chose 'ask_buyer');
// buyer_accept / buyer_decline record the buyer's answer to an offer; reject sends the reason back to the agent.
// @include travel.js
// @include plan.js
const req = $('Decision webhook').first().json.body || {};
const p = $('Get proposal').first().json;
const c = $('Current context').first().json;
const search = $('Current options').first().json; // fresh plan_rebooking result, used by a plan's ferry step only
const decision = String(req.decision || '').toLowerCase();
const operator = String(req.operator || '').trim();
const note = String(req.note || '').trim();
const fail = (error) => [{ json: { ok: false, error } }];
const NEEDS = { approve: 'pending', reject: 'pending', buyer_accept: 'offered', buyer_decline: 'offered' };
if (!p || !p.id) return fail(`No proposal #${req.proposal_id}`);
if (!NEEDS[decision]) return fail("decision must be 'approve', 'reject', 'buyer_accept' or 'buyer_decline'");
if (!operator) return fail('operator name is required (who decided)');
if (p.status !== NEEDS[decision]) return fail(`Proposal #${p.id} is ${p.status}; '${decision}' needs a ${NEEDS[decision]} plan. Nothing done.`);
if (decision === 'reject' && !note) return fail('Write why you reject it in the note: the agent uses the reason to make a better plan.');
const basis = JSON.parse(p.basis || '{}');
const nowStatus = c.snapshot?.order?.status;
// ponytail: order status is the only basis field re-checked; add last_event_id once live events flow in.
if (['approve', 'buyer_accept'].includes(decision) && basis.order_status && nowStatus !== basis.order_status) return fail(`Stale: order status changed ${basis.order_status} -> ${nowStatus} since proposal. Ask the agent to re-propose.`);
const payload = JSON.parse(p.payload || '{}');
const isPlan = ['plan', 'rebooking_plan'].includes(p.action);
const plan = isPlan ? JSON.parse(payload.detail || '{}') : null;
const now = Date.parse(c.snapshot?.snapshot_now);
const S = c.settings || {};
const hash = (s) => { let h = 2166136261; for (const ch of s) h = Math.imul(h ^ ch.charCodeAt(0), 16777619); return h >>> 0; };
// The workflows that made the plan (rationale is "journey: why | vehicle: why"), so a wake-up goes back to exactly them.
const workflows = [...new Set((String(p.rationale || '').match(/(?:^| \| )(\w+): /g) || []).map((x) => x.replace(/[ |:]/g, '')))].filter((w) => STAGES[w]).join(',');
const cust = c.snapshot?.customer?.name || 'buyer';
const opts = plan?.options || [];
const chosenKey = String(req.option || plan?.chosen || plan?.recommended || '').toUpperCase();
const opt = opts.find((o) => o.key === chosenKey);
if (opts.length && ['approve', 'buyer_accept'].includes(decision) && !opt) return fail(`option must be one of ${opts.map((o) => o.key).join(', ')}`);
// A before_booking check (filed as an open step with the plan) must be done before the plan is approved or offered.
const checks = (c.plan_steps || []).filter((s) => String(s.proposal_id) === String(p.id) && s.ref === 'before_booking');
const openCheck = checks.find((s) => s.status !== 'done');
if (isPlan && decision === 'approve' && openCheck) return fail(`Do the check first (step #${openCheck.id}, ${openCheck.status}): ${openCheck.detail}. Mark it done, then approve; if it cannot be done, mark it 'Could not do it' with the reason and the agent re-plans.`);
const priorSteps = (c.plan_steps || []).filter((s) => String(s.proposal_id) === String(p.id)).length;
const steps = [];
let status, result, kase, wake = false, wakeEvent = '', newPayload = '', closeBuyer = '';

// Books and sends the given plan lines (mock provider). Returns the status for the proposal.
const execute = (lines) => {
  // ponytail: mock provider. 'simulate' is a test-only switch: ferry_sold_out, ferry_timeout_once, hotel_timeout.
  const SIM = String(req.simulate || '');
  const book = (kind, what) => {
    const log = [];
    const tries = Number(S.booking_retries) || 3; // Settings page
    for (let attempt = 1; attempt <= tries; attempt++) {
      if (SIM === kind + '_sold_out') return { ok: false, attempts: attempt, note: 'sold out at booking time' };
      if (SIM === kind + '_timeout' || (SIM === kind + '_timeout_once' && attempt === 1)) { log.push(`attempt ${attempt}: provider timeout`); continue; }
      return { ok: true, attempts: attempt, ref: `MOCK-${kind.toUpperCase()}-${hash(p.id + what) % 1000000}`, note: log.concat(`attempt ${attempt}: confirmed (mock)`).join('; ') };
    }
    return { ok: false, attempts: tries, note: log.join('; ') + `; gave up after ${tries} attempts` };
  };
  // Final check right before booking: a sailing, train or flight that changed price or disappeared is not booked.
  let stale = null;
  for (const s of lines) {
    if (stale) break;
    if (s.kind === 'book_ferry') {
      const live = (search.options || []).find((o) => o.option_id === s.ref);
      const promised = opt ? opt.on_time : plan?.on_time; // what the approved option said
      stale = !live ? 'ferry option no longer in a fresh search' : live.ticket_cents !== s.cost_cents ? `ferry price changed EUR ${s.cost_cents / 100} -> ${live.ticket_cents / 100}`
        : promised !== false && live.on_time === false ? `the sailing no longer arrives on time (now ${live.late_hours} h late)` : null;
    } else if (['book_train', 'book_flight'].includes(s.kind)) {
      const t = searchTravel({ quotes: c.snapshot?.travel_options || [], from: s.search?.from_city, to: s.search?.to_city, earliest: s.search?.earliest ? Date.parse(s.search.earliest) : now });
      const live = t.ok && t.options.find((o) => o.option_id === s.ref);
      stale = !live ? `${s.kind} ${s.ref} no longer available` : live.cost_cents !== s.cost_cents ? `${s.kind} price changed EUR ${s.cost_cents / 100} -> ${live.cost_cents / 100}` : null;
    }
  }
  if (stale) return { stale };
  // A failed transport booking (ferry, train, flight) stops the rest: the plan no longer works. A failed hotel does not.
  let stopped = '', softFail = false;
  // ponytail: buyer and delivery-contact messages are mock-sent here; Phase 4 sends them over Telegram.
  const SENT = { customer_message: `MOCK sent to ${cust} (approved by ${operator})`, delivery_contact_message: `MOCK sent to the delivery contact (approved by ${operator})` };
  for (const s of lines.filter((x) => !x.before_booking)) { // checks were done before approval
    const row = { step_no: String(priorSteps + steps.length + 1), kind: s.kind, detail: s.detail, status: 'skipped', ref: '', attempts: '0', note: '' };
    if (stopped) row.note = `skipped: ${stopped}`;
    else if (SENT[s.kind]) Object.assign(row, { status: 'done', ref: `MOCK-MSG-${hash(p.id + s.kind) % 1000000}`, note: SENT[s.kind] });
    else if (s.kind === 'staff_task') Object.assign(row, { status: 'waiting_for_person', note: 'A person does this, then marks it done.' });
    else if (s.kind === 'buyer_decision') Object.assign(row, { status: 'done', ...(opt ? { detail: `Buyer chose option ${opt.key}` } : {}), note: `buyer answered: ${note || 'accepted'}` });
    else if (/^book_(ferry|train|flight|hotel)$/.test(s.kind)) {
      const kind = s.kind.slice(5), ref = s.ref || '', b = book(kind, ref || s.detail);
      Object.assign(row, { status: b.ok ? 'done' : 'failed', ref: b.ok ? b.ref : ref, attempts: String(b.attempts), note: b.note });
      if (!b.ok && ['ferry', 'train', 'flight'].includes(kind)) stopped = `${kind} not booked`;
      if (!b.ok) softFail = true;
    } else if (s.kind === 'notify_driver') {
      const refs = steps.filter((x) => x.status === 'done' && /^MOCK-(FERRY|TRAIN|FLIGHT|HOTEL)/.test(x.ref)).map((x) => x.ref).join(', ');
      const hotelFailed = steps.some((x) => x.kind === 'book_hotel' && x.status === 'failed');
      // propose_plan writes a placeholder for the not-yet-chosen option; now say which option and what was booked.
      const booked = steps.filter((x) => x.status === 'done' && /^book_/.test(x.kind)).map((x) => x.detail).join('; ');
      const said = s.detail.replace('the option the buyer chooses (booking details added when it is booked).', `${opt ? `option ${opt.key}` : 'the approved option'}${booked ? `: ${booked}` : ''}.`);
      Object.assign(row, { status: 'done', detail: `${said}${refs ? ` (booking refs: ${refs})` : ''}${hotelFailed ? ' Hotel not confirmed yet; ops will send it.' : ''}`, ref: `MOCK-MSG-${hash(p.id + 'driver') % 1000000}`, note: 'MOCK sent to driver' });
    } else if (s.kind === 'approve_cost') Object.assign(row, { status: 'done', ref: s.ref || `MOCK-COST-${hash(p.id + s.detail) % 1000000}`, note: `MOCK: approved by ${operator}, sent to payroll` });
    else if (s.kind === 'change_delivery_window') Object.assign(row, { status: 'done', ref: `MOCK-WIN-${hash(p.id + s.detail) % 1000000}`, note: 'MOCK: new delivery window recorded' });
    else if (s.kind === 'cancel_delivery') Object.assign(row, { status: 'done', ref: `MOCK-CANCEL-${hash(p.id + s.detail) % 1000000}`, note: 'MOCK: delivery cancelled as agreed with the buyer' });
    else if (s.kind === 'reassign_driver') Object.assign(row, { status: 'done', ref: s.ref, note: 'MOCK: assignment handed over' });
    steps.push(row);
  }
  return { stopped, softFail };
};

if (!isPlan) {
  // Single non-plan actions (older proposal kinds): approve = mock done, reject = nothing.
  status = decision === 'approve' ? 'executed' : 'rejected';
  result = decision === 'approve' ? `MOCK: done as approved: ${payload.detail}` : 'Rejected; nothing executed.';
  kase = { status: 'in_progress', owner: 'agent', summary: `#${p.id} ${p.action} ${status} by ${operator}. Agent continues.` };
} else if (decision === 'reject' || decision === 'buyer_decline') {
  const who = decision === 'reject' ? `rejected by ${operator}` : `declined by the buyer (recorded by ${operator})`;
  status = decision === 'reject' ? 'rejected' : 'declined';
  result = `Plan ${who}: ${note || 'no reason given'}. Nothing booked.`;
  if (decision === 'buyer_decline') closeBuyer = `declined: ${note || 'no reason given'}`;
  kase = { status: 'in_progress', owner: 'agent', summary: `Plan #${p.id} ${who}. The agent makes a new plan; it waits for approval.` };
  wake = true;
  wakeEvent = `Plan #${p.id} was ${who}. Reason: "${note || 'none given'}". Make one new plan that avoids this reason. Reuse finished stages; ask nobody again for facts you already have.`;
} else if (decision === 'approve' && (plan.needs_buyer || req.send === 'ask_buyer')) {
  // Offer to the buyer first. Nothing is booked; the driver keeps to the current plan until the buyer answers.
  const until = plan.valid_until ? Date.parse(plan.valid_until) : now + (Number(S.offer_valid_min) || 120) * 6e4;
  const untilLocal = plan.valid_until_local || localTime(until, plan.buyer_zone || 'Europe/Helsinki');
  newPayload = JSON.stringify({ ...payload, detail: JSON.stringify({ ...plan, valid_until: new Date(until).toISOString(), valid_until_local: untilLocal, offered_at: new Date(now).toISOString(), offered_by: operator }) });
  const msg = plan.steps.find((s) => s.kind === 'customer_message');
  const ask = plan.steps.find((s) => s.kind === 'buyer_decision');
  const choices = opts.length ? `options ${opts.map((o) => o.key).join(', ')}` : 'yes or no';
  execute([msg || { kind: 'customer_message', detail: `Offer for ${c.order_ref}: ${payload.summary}` }]);
  steps.push({ step_no: String(priorSteps + steps.length + 1), kind: 'notify_driver', detail: 'Keep to your current plan for now. We confirm any change as soon as the buyer has answered.', status: 'done', ref: `MOCK-MSG-${hash(p.id + 'keep') % 1000000}`, attempts: '0', note: 'MOCK sent to driver (status update, no new instruction)' });
  steps.push({ step_no: String(priorSteps + steps.length + 1), kind: 'buyer_decision', detail: ask?.detail || `Buyer chooses: ${choices}`, status: 'waiting_for_person', ref: '', attempts: '0', note: `Waiting for the buyer (${choices}) until ${untilLocal}. Record the answer with buyer accept or decline.` });
  status = 'offered';
  result = `Offer sent to the buyer (${choices}), valid until ${untilLocal}. Nothing booked yet.`;
  kase = { status: 'waiting_on_person', owner: 'buyer', summary: `Plan #${p.id} offered to the buyer until ${untilLocal}. Nothing booked until they answer.` };
} else {
  // Book now (employee approved an on-time plan), or the buyer accepted the offer.
  const accept = decision === 'buyer_accept';
  if (accept && plan.valid_until && now > Date.parse(plan.valid_until)) {
    status = 'expired';
    result = `Buyer answered after the offer deadline ${plan.valid_until_local || plan.valid_until}; decisions after that time are no longer valid. Nothing booked.`;
    closeBuyer = `answered too late (${note || 'accepted'})`;
    kase = { status: 'in_progress', owner: 'agent', summary: `Offer #${p.id} expired before the buyer answered. A revised plan follows; it waits for approval.` };
    wake = true;
    wakeEvent = `Offer #${p.id} expired at ${plan.valid_until_local || plan.valid_until} before the buyer answered (late answer: "${note || 'accept'}"${opt ? `, option ${opt.key}` : ''}). Make a revised plan with fresh options; it goes to the buyer again.`;
  } else {
    // Messages to the buyer were already sent with the offer; the delivery contact hears only now, with the final time.
    const lines = (opt ? opt.steps : []).concat(plan.steps).filter((s) => !(accept && s.kind === 'customer_message'));
    const r = execute(accept ? lines.filter((s) => s.kind !== 'buyer_decision') : lines);
    if (accept) closeBuyer = `accepted${opt ? ` option ${opt.key}` : ''}${note ? `: ${note}` : ''}`;
    const tag = opt ? ` option ${opt.key}` : '';
    if (r.stale) {
      status = 'failed'; result = `Final check before booking failed, nothing booked: ${r.stale}.`;
      kase = { status: 'in_progress', owner: 'agent', summary: `Plan #${p.id}${tag} not booked: ${r.stale}. The agent re-plans${accept ? ' and the buyer is asked again' : ''}.` };
      wake = true;
      wakeEvent = `Plan #${p.id}${tag} was ${accept ? 'accepted by the buyer' : `approved by ${operator}`} but the final check failed: ${r.stale}. Make a new plan with fresh options${accept ? '; the buyer must choose again' : ''}.`;
    } else {
      const open = steps.filter((x) => ['failed', 'waiting_for_person'].includes(x.status)).map((x) => `${x.kind} (${x.status})`);
      const booked = steps.filter((x) => x.status === 'done' && /^book_/.test(x.kind)).map((x) => x.ref);
      result = steps.map((x) => `${x.step_no}. ${x.kind}: ${x.status}${x.ref ? ' ' + x.ref : ''}`).join(' | ');
      if (r.stopped) {
        status = 'failed';
        kase = { status: 'in_progress', owner: 'agent', summary: `Plan #${p.id} failed: ${r.stopped} (${steps.find((x) => x.status === 'failed')?.note}). The agent is re-planning; its new plan waits for approval.` };
      } else {
        status = r.softFail ? 'partly_executed' : 'executed';
        kase = open.length ? { status: r.softFail ? 'needs_decision' : 'waiting_on_person', owner: 'operator', summary: `Plan #${p.id}${tag} done (mock)${booked.length ? ': ' + booked.join(', ') : ''}. Open: ${open.join(', ')}. Mark each step done when handled.` }
          : { status: 'in_progress', owner: 'agent', summary: `Plan #${p.id}${tag} done (mock)${booked.length ? ': ' + booked.join(', ') : ''}. Agent continues.` };
      }
      // Wake the agent when a booking failed (it re-plans; a person approves the new plan), or when nothing is left for a person.
      const failed = status === 'failed' || steps.some((x) => x.status === 'failed');
      // A buyer's answer to a question (no options) always goes back to the agent: it plans the next stage from it.
      wake = failed || !steps.some((x) => x.status === 'waiting_for_person') || (accept && !opts.length);
      const how = accept ? `accepted by the buyer${tag}${note ? ` ("${note}")` : ''}` : `approved by ${operator}${tag}`;
      wakeEvent = failed ? `Plan #${p.id} was ${how} but could not be fully booked (mock): ${result}. Re-plan only what failed: keep what is booked, the failed option is excluded from searches. File one new plan; a person approves it.`
        : `Plan #${p.id} was ${how} and executed (mock): ${result}. Do the next stage, or finish the case if nothing is left.`;
    }
  }
}
return [{ json: { ok: true, id: p.id, order_ref: p.order_ref, action: p.action, summary: payload.summary,
  update: { status, decided_by: operator, decision_note: note, result, ...(newPayload ? { payload: newPayload } : {}) }, case: kase,
  wake, wake_event: wakeEvent, workflows, close_buyer: closeBuyer,
  steps: steps.map((x) => ({ order_ref: p.order_ref, proposal_id: String(p.id), ...x, updated_by: 'act workflow' })) } }];

const d = $('Re-check and execute (mock)').first().json;
const steps = $('Insert steps').isExecuted ? $('Insert steps').all().map(i => ({ step_id: i.json.id, kind: i.json.kind, status: i.json.status, ref: i.json.ref, note: i.json.note })) : [];
return [{ json: { ok: true, proposal_id: d.id, order_ref: d.order_ref, status: d.update.status, result: d.update.result, case: d.case, steps, agent_woken: $('Wake agent').isExecuted } }];

// Messages this decision released (status done this run) go out over Telegram. The buyer's offer carries one button per option.
// @include offer.js
const d = $('Re-check and execute (mock)').first().json;
const ROLE = { customer_message: 'buyer', delivery_contact_message: 'delivery_contact', notify_driver: 'driver' };
let plan = {}; try { plan = JSON.parse(JSON.parse(d.update.payload || '{}').detail || '{}'); } catch {}
const offer = d.update.status === 'offered';
const buttons = offer ? offerButtons(plan) : [];
const items = (d.steps || []).filter((s) => ROLE[s.kind] && s.status === 'done').map((s) => ({ json: { order_ref: d.order_ref, role: ROLE[s.kind], proposal_id: String(d.id), kind: s.kind,
  text: s.kind === 'customer_message' && offer ? `${s.detail}\n\nPlease choose by ${plan.valid_until_local || 'the deadline'}.` : s.detail, buttons: JSON.stringify(s.kind === 'customer_message' ? buttons : []) } }));
return items.length ? items : [{ json: { skip: true } }];
